mapper.select:
SELECT status
FROM t_exam_paper_answer
where id = #{paperAnswerId,jdbcType=BIGINT}

SELECT ${column} from t_exam_paper_answer  where
deleted = 0 and exam_paper_build_id = #{examPaperBuildId}

  and status = #{status}


  and passed = #{passed}

SELECT user_score from t_exam_paper_answer  where
deleted = 0 and exam_paper_build_id = #{examPaperBuildId}

  and status = #{status}


  and passed = #{passed}

SELECT pa.id,u.user_name userName ,u.real_name realName ,u.department_id departmentId ,u.id_card idCard,u.work_no workNo,u.job_title jobTitle,pa.user_score userScore,pa.paper_score paperScore,
       pa.question_correct questionCorrect,pa.question_count questionCount,pa.do_time doTime,pa.status status,pa.passed passed,pa.create_time createTime,pa.preview_file_path previewFilePath
      from t_user u LEFT JOIN t_exam_paper_answer pa on u.id=pa.create_user and pa.deleted = 0 and pa.exam_paper_id = #{examPaperId}
      where  u.deleted= 0  and system_role = 1 and u.status = 1

          and u.user_name like concat('%',#{userName},'%')


          and u.department_id in

          #{id}




          and pa.status = #{status}


          and pa.user_score is null



        and pa.user_score >= #{minScore}


        and pa.user_score <= #{maxScore}


        and pa.create_user = #{dataFilterUserId}


        and pa.create_department_id in

          #{item}


       and (
         u.id in (select user_id from t_exam_paper_user where deleted = 0 and exam_paper_id = #{examPaperId})
         or
         u.department_id in (select department_id from t_exam_paper_department where  deleted=0 and exam_paper_id = #{examPaperId})
       )

SELECT create_time as name,COUNT(create_time) as value from
        (
		  SELECT DATE_FORMAT(create_time,'%Y-%m-%d') as create_time from t_exam_paper_answer
			WHERE   create_time  between  #{startTime}  and  #{endTime}
		) a
GROUP BY create_time

select  *  from t_exam_paper_answer
where deleted = 0 and exam_paper_id = #{examPaperId} and create_user=#{userId}
limit 1

select id from t_exam_paper_answer
where deleted = 0 and status = 1
      and exam_paper_build_id = #{examPaperBuildId} and id != #{id}

       and create_user = #{dataFilterUserId}


        and create_department_id in

          #{item}


limit 1
